package com.collabspace.service; import com.collabspace.entity.User; import com.collabspace.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class CurrentUserService {private final UserRepository users; public User get(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return users.findByEmail(email).orElseThrow(()->new IllegalStateException("Authenticated user not found"));}}